<?php
use PreConselho\Support\Csrf;
use PreConselho\Support\FormRecovery;
$formRecovery=FormRecovery::consume($_SERVER['REQUEST_URI']??'/');
$content=$content??'';
$user=$_SESSION['user']??null;
$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';
$isLogin=$path==='/login'&&!$user;
$isPortal=$path==='/';
$isApc=str_starts_with($path,'/apc');
$isCouncil=!$isPortal&&!$isApc&&!$isLogin;
$roleLabels=['ADMIN'=>'Administrador','COORDENADOR'=>'Coordenação','PROFESSOR'=>'Professor'];
$brandTitle=($isPortal||$isLogin)?'Gestão Pedagógica':($isApc?'APCs':'Conselho de Classe');
$moduleName=$isPortal?'Visão geral':($isApc?'Atividades Pedagógicas Complementares':'Conselho de Classe');
$nameParts=$user?preg_split('/\s+/',trim((string)$user['nome'])):[];$userInitials=$user?mb_strtoupper(mb_substr((string)($nameParts[0]??''),0,1).mb_substr((string)($nameParts[count($nameParts)-1]??''),0,1)):'';
$apcCalendarActive=$isApc&&(str_starts_with($path,'/apc/calendario')||str_starts_with($path,'/apc/eventos/'));$apcAdminActive=str_starts_with($path,'/apc/admin');$apcHomeActive=$isApc&&!$apcCalendarActive&&!$apcAdminActive;
$councilConsolidatedActive=str_starts_with($path,'/consolidados');$councilAdminActive=str_starts_with($path,'/admin');$councilHomeActive=$isCouncil&&!$councilConsolidatedActive&&!$councilAdminActive;
$assetVersion=static function(string $file):string{$path=dirname(__DIR__,2).'/public/assets/'.$file;$modified=is_file($path)?filemtime($path):false;return $modified===false?'1':(string)$modified;};
$areaLinks=[];
if($user&&$isApc){
    $areaLinks=[['/apc',$user['perfil']==='PROFESSOR'?'Minhas APCs':'Envios',$path==='/apc'||str_starts_with($path,'/apc/envios/')],['/apc/calendario','Calendário',$apcCalendarActive]];
    if($user['perfil']==='ADMIN')$areaLinks[]=['/apc/admin','Eventos',$apcAdminActive];
}elseif($user&&!$isPortal){
    $areaLinks=[['/conselho','Painel do Conselho',$councilHomeActive]];
    if($user['perfil']!=='PROFESSOR')$areaLinks[]=['/consolidados','Consolidado',$councilConsolidatedActive];
    if($user['perfil']==='ADMIN')$areaLinks=array_merge($areaLinks,[['/admin','Administração',$path==='/admin'],['/admin/auditoria','Auditoria',$path==='/admin/auditoria']]);
}
