<main id="conteudo"><?php if($formRecovery):?><div id="form-error" class="error" role="alert" tabindex="-1" data-form-recovery="<?=e((string)json_encode($formRecovery,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT))?>"><div><strong><?=e($formRecovery['message'])?></strong><p>Confira o formulário abaixo. Os campos preenchidos foram mantidos.<?php if($formRecovery['reselectFile']):?> Selecione o arquivo novamente para continuar.<?php endif;?></p></div></div><?php endif;?><?php if(!empty($_SESSION['flash'])):?><div class="flash" role="status"><span aria-hidden="true">✓</span><span><?=e($_SESSION['flash']);unset($_SESSION['flash']);?></span></div><?php endif;?><?=$content?><?php if(isset($report)&&($user['perfil']??'')==='ADMIN'&&$report['status']==='APROVADO'&&$report['periodo_status']!=='ENCERRADO'):?><section class="card danger-zone"><div><p class="eyebrow">Ação administrativa</p><h2>Reabrir relatório aprovado</h2><p>O relatório voltará ao professor para ajustes e a ação ficará registrada no histórico.</p></div><form method="post" action="/admin/relatorios/<?=e($report['id'])?>/reabrir"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><label>Motivo da reabertura <textarea name="justificativa" required maxlength="2000" placeholder="Explique por que o relatório precisa ser alterado"></textarea></label><button class="danger" data-confirm="Confirma a reabertura deste relatório?">Reabrir relatório</button></form></section><?php endif;?></main><?php if(!$isLogin):?><footer><?=e($brandTitle)?> <span>•</span> Gestão pedagógica da escola</footer><?php endif;?><script src="/assets/app.js?v=<?=e($assetVersion('app.js'))?>" defer></script><?php if($isApc):?><?php foreach(['apc-context.js'] as $apcAsset):?><?php if(is_file(dirname(__DIR__,2).'/public/assets/'.$apcAsset)):?><script src="/assets/<?=e($apcAsset)?>?v=<?=e($assetVersion($apcAsset))?>" defer></script><?php endif;?><?php endforeach;?><?php endif;?><?php if(is_file(dirname(__DIR__,2).'/public/assets/collaboration.js')):?><script src="/assets/collaboration.js?v=<?=e($assetVersion('collaboration.js'))?>" defer></script><?php endif;?></body></html>
